<?php $title = $product['name'] . ' | ShopStack'; require __DIR__ . '/../layouts/header.php'; ?><div class="detail"><div class="product-image large"><?= e(strtoupper(substr($product['name'], 0, 1))) ?></div><div><p class="eyebrow"><?= e($product['category_name']) ?></p><h1><?= e($product['name']) ?></h1><p class="lead"><?= e($product['description']) ?></p><p class="price"><?= money($product['price']) ?></p><p><?= (int) $product['stock'] ?> szt. dostępnych</p><?php if ((int) $product['stock'] > 0): ?><form method="post" action="<?= e($config['url']) ?>/cart/add" class="buy"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><input type="number" name="quantity" value="1" min="1" max="<?= e($product['stock']) ?>"><button class="button">Dodaj do koszyka</button></form><?php else: ?><p class="muted">Produkt chwilowo niedostępny.</p><?php endif; ?></div></div><?php require __DIR__ . '/../layouts/footer.php'; ?>
